"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type KeyboardEvent, useCallback, useId, useState, type CSSProperties } from "react";

import { SparklesIcon } from "@/components/blocks/parts/icons";
import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { answerLabel, type Answers, QUESTIONS, setupTasks } from "./onboarding-survey/data";
import { OptionCards } from "./onboarding-survey/option-cards";
import { SetupChecklist } from "./onboarding-survey/setup-checklist";
import { focusRoving } from "./shared/roving";
import { SpringHeight } from "./shared/spring-height";

const CHECKLIST = QUESTIONS.length;
const SUMMARY = QUESTIONS.length + 1;

const isTyping = (target: EventTarget) => target instanceof HTMLElement && ["INPUT", "TEXTAREA"].includes(target.tagName);

/**
 * A short survey after sign-up: one question per step with large cards,
 * then a checklist that sets the workspace up from the answers, then a
 * summary where any answer can be changed. Number keys pick an option.
 */
export function OnboardingSurvey({ className }: { className?: string }) {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState<Answers>({});
  const [editing, setEditing] = useState(false);
  const [opened, setOpened] = useState(false);
  const titleId = useId();
  const reduceMotion = useReducedMotion();

  const question = QUESTIONS[step];
  const progress = Math.min(1, (step + 1) / (QUESTIONS.length + 1));

  const next = () => setStep((current) => (editing ? SUMMARY : current + 1));
  const finishChecklist = useCallback(() => setStep(SUMMARY), []);

  const pick = (value: string) => {
    if (question) setAnswers((current) => ({ ...current, [question.id]: value }));
  };

  const onKeyDown = (event: KeyboardEvent) => {
    if (!question || isTyping(event.target) || event.metaKey || event.ctrlKey || event.altKey) return;
    const option = question.options[Number(event.key) - 1];
    if (option) {
      event.preventDefault();
      pick(option.value);
      // Focus follows the pick, so Enter and the arrows carry on from the chosen card.
      focusRoving(event.currentTarget.querySelector("[role=radiogroup]"), Number(event.key) - 1);
    }
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className} onKeyDown={onKeyDown}>
      <header className="flex flex-col gap-3 border-b border-border px-5 py-4">
        <div className="flex items-center justify-between gap-3">
          <h2 id={titleId} className="text-base font-semibold">
            Welcome to Fernhill
          </h2>
          <span className="text-xs text-muted-foreground tabular-nums">
            {step < CHECKLIST ? `Step ${step + 1} of ${QUESTIONS.length}` : step === CHECKLIST ? "Setting up" : "Ready"}
          </span>
        </div>
        <div
          role="progressbar"
          aria-label="Survey progress"
          aria-valuemin={0}
          aria-valuemax={100}
          aria-valuenow={Math.round(progress * 100)}
          className="h-1.5 overflow-hidden rounded-full bg-muted"
        >
          <span
            className="block h-full origin-left scale-x-(--progress) rounded-full bg-chart-1 motion-safe:transition-transform motion-safe:duration-500 motion-safe:ease-out"
            style={
            // SAFETY: the object sets only CSS custom properties, which React passes to the element as they are.
            { "--progress": progress } as CSSProperties
          }
          />
        </div>
      </header>

      <div className="p-5">
        <SpringHeight>
          <AnimatePresence mode="wait" initial={false}>
            <motion.div
              key={step}
              initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: "0.5rem" }}
              animate={{ opacity: 1, y: 0 }}
              exit={reduceMotion ? { opacity: 0, transition: { duration: 0 } } : { opacity: 0, y: "-0.25rem" }}
              transition={{ duration: reduceMotion ? 0 : 0.18, ease: "easeOut" }}
              className="flex flex-col gap-4 pb-1"
            >
              {question ? (
                <>
                  <div>
                    <h3 className="text-lg font-semibold">{question.title}</h3>
                    <p className="text-sm text-muted-foreground">{question.helper} Press 1 to 4 to pick.</p>
                  </div>
                  <OptionCards question={question} value={answers[question.id]} onChange={pick} onSubmit={next} />
                </>
              ) : null}
              {step === CHECKLIST ? (
                <>
                  <div>
                    <h3 className="flex items-center gap-2 text-lg font-semibold">
                      <SparklesIcon aria-hidden="true" className="size-4 text-chart-1" />
                      Setting up your workspace
                    </h3>
                    <p className="text-sm text-muted-foreground">This takes a few seconds.</p>
                  </div>
                  <SetupChecklist tasks={setupTasks(answers)} onFinished={finishChecklist} />
                </>
              ) : null}
              {step === SUMMARY ? (
                <>
                  <div>
                    <h3 className="text-lg font-semibold">You are all set</h3>
                    <p className="text-sm text-muted-foreground">Change any answer and we adjust your workspace.</p>
                  </div>
                  <dl className="flex flex-col rounded-xl border border-border py-1">
                    {QUESTIONS.map((item, index) => (
                      <div key={item.id} className="flex items-center justify-between gap-3 px-4 py-2">
                        <div className="min-w-0">
                          <dt className="text-xs text-muted-foreground">{item.title}</dt>
                          <dd className="text-sm font-medium">{answerLabel(item, answers)}</dd>
                        </div>
                        <Button
                          variant="ghost"
                          size="sm"
                          aria-label={`Change: ${item.title}`}
                          onClick={() => {
                            setEditing(true);
                            setStep(index);
                          }}
                        >
                          Change
                        </Button>
                      </div>
                    ))}
                  </dl>
                </>
              ) : null}
            </motion.div>
          </AnimatePresence>
        </SpringHeight>
      </div>

      {step === CHECKLIST ? null : (
        <footer className="flex flex-wrap items-center justify-between gap-2 border-t border-border px-5 py-4">
          {step === SUMMARY ? (
            <>
              <p role="status" className="text-sm text-muted-foreground">
                {opened ? "Opening your workspace." : ""}
              </p>
              <Button onClick={() => setOpened(true)}>Open my workspace</Button>
            </>
          ) : (
            <>
              <Button variant="ghost" onClick={() => setStep(step - 1)} disabled={step === 0 || editing}>
                Back
              </Button>
              <div className="flex gap-2">
                <Button variant="ghost" onClick={next}>
                  Skip
                </Button>
                <Button onClick={next} disabled={!question || !answers[question.id]}>
                  {editing ? "Save answer" : "Continue"}
                </Button>
              </div>
            </>
          )}
        </footer>
      )}
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

