import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** One survey question with its options. */
export interface Question {
  id: "practice" | "size" | "booking";
  title: string;
  helper: string;
  options: { value: string; label: string; helper: string }[];
}

/** The questions, one per step. */
export const QUESTIONS: Question[] = [
  {
    id: "practice",
    title: "What kind of practice do you run?",
    helper: "We set up visit types that fit your work.",
    options: [
      { value: "physio", label: "Physiotherapy", helper: "Assessments, follow-ups, classes" },
      { value: "dental", label: "Dental", helper: "Check-ups, hygiene, treatment" },
      { value: "therapy", label: "Talking therapy", helper: "Weekly sessions, intake calls" },
      { value: "general", label: "General practice", helper: "Short visits, same-day slots" },
    ],
  },
  {
    id: "size",
    title: "How many practitioners take bookings?",
    helper: "Each one gets a calendar of their own.",
    options: [
      { value: "1", label: "Just me", helper: "One calendar" },
      { value: "3", label: "2 to 5", helper: "A small team" },
      { value: "10", label: "6 to 15", helper: "Several rooms" },
      { value: "20", label: "More than 15", helper: "More than one site" },
    ],
  },
  {
    id: "booking",
    title: "How do patients book today?",
    helper: "We bring your existing bookings across.",
    options: [
      { value: "phone", label: "Phone calls", helper: "The front desk takes them" },
      { value: "site", label: "Another booking site", helper: "We import the calendar" },
      { value: "paper", label: "A paper diary", helper: "We help you type it in" },
      { value: "walk-in", label: "Mostly walk-ins", helper: "Queue and same-day slots" },
    ],
  },
];

/** The answers so far, by question id. */
export type Answers = Partial<Record<Question["id"], string>>;

/** The label of the chosen option for a question, or a note that it was skipped. */
export function answerLabel(question: Question, answers: Answers) {
  return question.options.find((option) => option.value === answers[question.id])?.label ?? "Skipped";
}

/** The setup tasks the closing step runs, worded from the answers. */
export function setupTasks(answers: Answers) {
  const practice = QUESTIONS[0]!.options.find((option) => option.value === answers.practice)?.label.toLowerCase() ?? "your practice";
  const people = Number(answers.size ?? "1");
  return [
    `Add visit types for ${practice}`,
    people === 1 ? "Create your calendar" : `Create ${people === 3 ? "5" : people === 10 ? "15" : "20"} practitioner calendars`,
    answers.booking === "site" ? "Import bookings from your old site" : "Turn on text reminders",
    "Prepare your booking page",
  ];
}

"use client";

import { useRef } from "react";

import { cn } from "@/lib/utils";

import { focusRoving, rovingIndex } from "../shared/roving";
import type { Question } from "./data";

/** Props for the large option cards of one question. */
export interface OptionCardsProps {
  question: Question;
  value: string | undefined;
  onChange: (value: string) => void;
  /** Enter on a card continues to the next step. */
  onSubmit: () => void;
}

/**
 * The options of one question as a radio group of large cards, each with its
 * number key. Arrows move and pick, Space picks, Enter continues with the
 * chosen card, or picks the focused card when none is chosen.
 */
export function OptionCards({ question, value, onChange, onSubmit }: OptionCardsProps) {
  const groupRef = useRef<HTMLDivElement>(null);
  const index = question.options.findIndex((option) => option.value === value);

  return (
    <div
      ref={groupRef}
      role="radiogroup"
      aria-label={question.title}
      className="grid gap-2 @lg:grid-cols-2"
      onKeyDown={(event) => {
        const next = rovingIndex(event, Math.max(0, index), question.options.length);
        const option = next === null ? undefined : question.options[next];
        if (next === null || !option) return;
        event.preventDefault();
        onChange(option.value);
        focusRoving(groupRef.current, next);
      }}
    >
      {question.options.map((option, position) => {
        const checked = option.value === value;
        return (
          <div
            key={option.value}
            role="radio"
            aria-checked={checked}
            aria-keyshortcuts={String(position + 1)}
            tabIndex={checked || (index === -1 && position === 0) ? 0 : -1}
            data-roving={position}
            onClick={() => onChange(option.value)}
            onKeyDown={(event) => {
              if (event.key === " ") {
                event.preventDefault();
                onChange(option.value);
              } else if (event.key === "Enter") {
                event.preventDefault();
                // Keep an answer picked by number key; pick the focused card only when nothing is chosen yet.
                if (index === -1) onChange(option.value);
                onSubmit();
              }
            }}
            className={cn(
              "relative isolate flex cursor-pointer items-center gap-3 rounded-xl border p-4 outline-none focus-visible:ring-2 focus-visible:ring-ring motion-safe:transition-colors",
              checked ? "border-chart-1" : "border-border hover:border-foreground/30",
            )}
          >
            <span aria-hidden="true" className={cn("absolute inset-0 -z-10 rounded-xl", checked ? "bg-chart-1/10" : undefined)} />
            <span
              aria-hidden="true"
              className={cn(
                "flex size-7 shrink-0 items-center justify-center rounded-lg border text-xs font-semibold tabular-nums",
                checked ? "border-transparent bg-chart-1 text-primary-foreground" : "border-border text-muted-foreground",
              )}
            >
              {position + 1}
            </span>
            <span className="flex min-w-0 flex-col">
              <span className="text-sm font-medium">{option.label}</span>
              <span className="text-xs text-muted-foreground">{option.helper}</span>
            </span>
          </div>
        );
      })}
    </div>
  );
}

import type { KeyboardEvent } from "react";

/** Which arrow keys step through a list. */
export type RovingAxis = "vertical" | "horizontal" | "both";

const BACK = { vertical: ["ArrowUp"], horizontal: ["ArrowLeft"], both: ["ArrowUp", "ArrowLeft"] } as const;
const FORWARD = { vertical: ["ArrowDown"], horizontal: ["ArrowRight"], both: ["ArrowDown", "ArrowRight"] } as const;

/**
 * Reads one key press on a list of `count` items and returns the index it
 * moves to, or null for a key the list does not handle. Arrows step and wrap
 * at the ends; Home and End go to the first and last item. The caller
 * prevents the default only when an index comes back.
 */
export function rovingIndex(event: KeyboardEvent, current: number, count: number, axis: RovingAxis = "both"): number | null {
  if (count === 0) return null;
  const back: readonly string[] = BACK[axis];
  const forward: readonly string[] = FORWARD[axis];
  if (back.includes(event.key)) return (current - 1 + count) % count;
  if (forward.includes(event.key)) return (current + 1) % count;
  if (event.key === "Home") return 0;
  if (event.key === "End") return count - 1;
  return null;
}

/** Moves focus to the element in `container` that carries `data-roving` equal to `index`, after React has painted. */
export function focusRoving(container: HTMLElement | null, index: number) {
  requestAnimationFrame(() => {
    container?.querySelector<HTMLElement>(`[data-roving="${index}"]`)?.focus();
  });
}

"use client";

import { useEffect, useState } from "react";

import { CheckIcon } from "@/components/blocks/parts/icons";
import { cn } from "@/lib/utils";

import { LoaderIcon } from "../icons";

/** Props for the closing checklist. */
export interface SetupChecklistProps {
  tasks: string[];
  onFinished: () => void;
}

const STEP_MS = 750;

/**
 * Ticks off the setup tasks one by one, with a spinner on the task in hand.
 * A live line names each task as it finishes. The timers stop if the step
 * goes away early.
 */
export function SetupChecklist({ tasks, onFinished }: SetupChecklistProps) {
  const [done, setDone] = useState(0);

  useEffect(() => {
    if (done > tasks.length) return;
    const timer = window.setTimeout(() => (done === tasks.length ? onFinished() : setDone(done + 1)), done === tasks.length ? 450 : STEP_MS);
    return () => window.clearTimeout(timer);
  }, [done, tasks.length, onFinished]);

  return (
    <div className="flex flex-col gap-3">
      <ul className="flex flex-col gap-2.5">
        {tasks.map((task, index) => {
          const finished = index < done;
          const live = index === done;
          return (
            <li key={task} className={cn("flex items-center gap-3 text-sm motion-safe:transition-colors", finished || live ? "text-foreground" : "text-muted-foreground")}>
              <span
                aria-hidden="true"
                className={cn(
                  "flex size-5 shrink-0 items-center justify-center rounded-full border motion-safe:transition-colors",
                  finished ? "border-transparent bg-chart-2 text-primary-foreground" : "border-border",
                )}
              >
                {finished ? <CheckIcon className="size-3" /> : live ? <LoaderIcon className="size-3.5 motion-safe:animate-spin" /> : null}
              </span>
              {task}
            </li>
          );
        })}
      </ul>
      <p role="status" className="sr-only">
        {done > 0 ? `${tasks[done - 1]}, done.` : ""}
      </p>
    </div>
  );
}

